<script setup>
import {ref,computed,watch} from 'vue';import {Head,useForm,router,Link} from '@inertiajs/vue3';import AppLayout from '../Layouts/AppLayout.vue';
const props=defineProps({questions:Object,groups:Array,part:String});
const partFilter=ref(props.part||'');watch(partFilter,v=>router.get('/questions',{part:v},{preserveState:true,replace:true}));
const group=useForm({part:3,title:'',passage:'',media_path:''});
const q=useForm({part:5,question_group_id:'',content:'',options:{A:'',B:'',C:'',D:''},correct_option:'A',explanation:'',difficulty:'medium'});
const availableGroups=computed(()=>props.groups.filter(g=>g.part===Number(q.part)));
watch(()=>q.part,()=>q.question_group_id='');
const submit=()=>q.post('/questions',{onSuccess:()=>q.reset('content','options','explanation')});
</script>
<template><Head title="Ngân hàng câu hỏi"/><AppLayout><h1>Ngân hàng câu hỏi TOEIC</h1><p class="muted">Hỗ trợ 7 Part · Câu hỏi nhóm dùng chung đoạn đọc hoặc audio</p><div class="card"><h2>Tạo nhóm tư liệu (Part 3, 4, 6, 7)</h2><form class="formgrid" @submit.prevent="group.post('/question-groups',{onSuccess:()=>group.reset('title','passage','media_path')})"><div class="field"><label>Part</label><select v-model.number="group.part"><option v-for="n in [1,2,3,4,6,7]" :value="n">Part {{n}}</option></select></div><div class="field"><label>Tên nhóm</label><input v-model="group.title" placeholder="Hội thoại văn phòng 01"/></div><div class="field"><label>Đường dẫn media nội bộ (giai đoạn kế tiếp sẽ có upload)</label><input v-model="group.media_path" placeholder="audio/conversation-01.mp3"/></div><div class="field"><label>Đoạn văn/Transcript</label><textarea v-model="group.passage" rows="3"/></div><button :disabled="group.processing">Lưu nhóm tư liệu</button><div class="error">{{Object.values(group.errors).join(' · ')}}</div></form></div><div class="card" style="margin-top:20px"><h2>Tạo câu hỏi</h2><form @submit.prevent="submit"><div class="formgrid"><div class="field"><label>Part</label><select v-model.number="q.part"><option v-for="n in 7" :value="n">Part {{n}}</option></select></div><div class="field"><label>Nhóm tư liệu</label><select v-model="q.question_group_id"><option value="">Không có nhóm</option><option v-for="g in availableGroups" :value="g.id" :key="g.id">#{{g.id}} · {{g.title||'Nhóm không tên'}}</option></select></div></div><div class="field"><label>Nội dung câu hỏi</label><textarea v-model="q.content" rows="3" required/></div><div class="formgrid"><div v-for="o in ['A','B','C','D']" :key="o" class="field"><label>Đáp án {{o}}</label><input v-model="q.options[o]" :required="o==='A'||o==='B'"/></div><div class="field"><label>Đáp án đúng</label><select v-model="q.correct_option"><option v-for="o in ['A','B','C','D']">{{o}}</option></select></div><div class="field"><label>Độ khó</label><select v-model="q.difficulty"><option value="easy">Dễ</option><option value="medium">Trung bình</option><option value="hard">Khó</option></select></div></div><div class="field"><label>Giải thích đáp án</label><textarea v-model="q.explanation" rows="2"/></div><button :disabled="q.processing">Lưu câu hỏi nháp</button><div class="error">{{Object.values(q.errors).join(' · ')}}</div></form></div><div class="card" style="margin-top:20px"><h2>Danh sách câu hỏi</h2><div class="field"><label>Lọc Part</label><select v-model="partFilter"><option value="">Tất cả</option><option v-for="n in 7" :value="n">Part {{n}}</option></select></div><div class="tablewrap"><table><thead><tr><th>Mã</th><th>Part</th><th>Nội dung</th><th>Độ khó</th><th>Trạng thái</th></tr></thead><tbody><tr v-for="item in questions.data" :key="item.id"><td>#{{item.id}}</td><td>{{item.part}}</td><td style="max-width:400px;overflow:hidden;text-overflow:ellipsis">{{item.content}}</td><td>{{item.difficulty}}</td><td>{{item.status}}</td></tr></tbody></table></div><div class="pagination"><Link v-if="questions.prev_page_url" :href="questions.prev_page_url">← Trước</Link><span>Trang {{questions.current_page}} / {{questions.last_page}}</span><Link v-if="questions.next_page_url" :href="questions.next_page_url">Tiếp →</Link></div></div></AppLayout></template>
